CREATE OR REPLACE FUNCTION public.save_inspection(device_token uuid, target_field text, entry_note text, entry_photo text, entry_outcome text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions AS $$ DECLARE result uuid; BEGIN IF device_token IS NULL THEN RAISE EXCEPTION 'Device token required'; END IF; INSERT INTO public.field_inspections(device_hash, field_id, note, photo, outcome) VALUES (encode(sha256(device_token::text::bytea), 'hex'), target_field, entry_note, NULLIF(entry_photo, ''), entry_outcome) RETURNING id INTO result; RETURN result; END $$;